//! The one error type of the CLI, its exit codes, and how it renders on stderr.
use std::{fmt, io};

use serde_json::{json, Value};

/// Exit codes, stable across versions: scripts and agents branch on them.
pub mod exit {
    /// Success.
    pub const OK: u8 = 0;
    /// A bug or an unexpected condition: I/O, a response the SDK could not decode.
    pub const INTERNAL: u8 = 1;
    /// Invalid arguments, `--data`, field flags or `--jq` filter.
    pub const USAGE: u8 = 2;
    /// The API answered 4xx.
    pub const API_CLIENT: u8 = 3;
    /// The API answered 5xx, or any other non-2xx status.
    pub const API_SERVER: u8 = 4;
    /// No response: connection failure or timeout.
    pub const NETWORK: u8 = 5;
    /// Missing credentials, unknown profile, unreadable config file.
    pub const CONFIG: u8 = 6;
    /// The request succeeded but its output could not be produced, e.g. `--jq` failed on the
    /// response: the unfiltered response was printed.
    pub const OUTPUT: u8 = 7;
}

/// What went wrong, as `error.kind` in the JSON rendering.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum ErrorKind {
    Usage,
    Config,
    Api,
    Network,
    Timeout,
    Decode,
    Internal,
    Output,
}

impl ErrorKind {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Usage => "usage",
            Self::Config => "config",
            Self::Api => "api",
            Self::Network => "network",
            Self::Timeout => "timeout",
            Self::Decode => "decode",
            Self::Internal => "internal",
            Self::Output => "output",
        }
    }
}

type Source = Box<dyn std::error::Error + Send + Sync>;

/// Every failure of a command. Generated code converts the SDK's error into it with the
/// constructors below (see `From<sdk::Error>` in `examples/acme.rs`), so `?` works on calls.
#[derive(Debug)]
pub struct CliError(Box<Inner>);

#[derive(Debug)]
struct Inner {
    kind: ErrorKind,
    message: String,
    status: Option<u16>,
    body: Option<Value>,
    request_id: Option<String>,
    retry_after: Option<u64>,
    errors: Option<Vec<Value>>,
    source: Option<Source>,
}

impl CliError {
    fn new(kind: ErrorKind, message: impl Into<String>) -> Self {
        Self(Box::new(Inner {
            kind,
            message: message.into(),
            status: None,
            body: None,
            request_id: None,
            retry_after: None,
            errors: None,
            source: None,
        }))
    }

    pub fn usage(message: impl Into<String>) -> Self {
        Self::new(ErrorKind::Usage, message)
    }

    pub fn config(message: impl Into<String>) -> Self {
        Self::new(ErrorKind::Config, message)
    }

    pub fn internal(message: impl Into<String>) -> Self {
        Self::new(ErrorKind::Internal, message)
    }

    /// The call succeeded but printing its response failed after the raw response was printed.
    pub fn output(message: impl Into<String>) -> Self {
        Self::new(ErrorKind::Output, message)
    }

    /// Several problems of the input at once: `{"path", "flag", "message"}` objects, rendered
    /// as `errors` and joined into the message.
    pub fn invalid_input(what: &str, errors: Vec<Value>) -> Self {
        let lines: Vec<String> = errors
            .iter()
            .map(|error| {
                let text = |key: &str| error.get(key).and_then(Value::as_str).unwrap_or_default();
                let flag = match text("flag") {
                    "" => String::new(),
                    flag => format!(" ({flag})"),
                };
                match text("path") {
                    "" => text("message").to_owned(),
                    path => format!("{path}{flag}: {}", text("message")),
                }
            })
            .collect();
        let mut error = Self::usage(format!("invalid {what}: {}", lines.join("; ")));
        error.0.errors = Some(errors);
        error
    }

    pub fn timeout() -> Self {
        Self::new(ErrorKind::Timeout, "request timed out")
    }

    pub fn network(error: impl fmt::Display) -> Self {
        Self::new(ErrorKind::Network, format!("connection error: {error}"))
    }

    pub fn decode(error: impl fmt::Display) -> Self {
        Self::new(
            ErrorKind::Decode,
            format!("unexpected response body: {error}"),
        )
    }

    /// The SDK could not build the request, e.g. an invalid header value or base URL.
    pub fn invalid_request(error: impl fmt::Display) -> Self {
        Self::new(ErrorKind::Usage, format!("invalid request: {error}"))
    }

    /// A non-2xx response. The body is kept as JSON when it is JSON, as a string otherwise.
    pub fn api(status: u16, body: &[u8]) -> Self {
        let body = if body.is_empty() {
            None
        } else {
            Some(
                serde_json::from_slice(body)
                    .unwrap_or_else(|_| Value::String(String::from_utf8_lossy(body).into_owned())),
            )
        };
        let detail = body.as_ref().and_then(body_message);
        let message = match detail {
            Some(detail) if detail.starts_with("API error") => detail,
            Some(detail) => format!("API error {status}: {detail}"),
            None => format!("API error {status}"),
        };
        let mut error = Self::new(ErrorKind::Api, message);
        error.0.status = Some(status);
        error.0.body = body;
        error
    }

    /// The `Retry-After` of a response, in seconds.
    #[must_use]
    pub fn with_retry_after(mut self, seconds: Option<u64>) -> Self {
        self.0.retry_after = seconds;
        self
    }

    #[must_use]
    pub fn with_request_id(mut self, request_id: Option<&str>) -> Self {
        self.0.request_id = request_id.map(str::to_owned);
        self
    }

    /// Keeps the underlying error, printed with `--debug`.
    #[must_use]
    pub fn with_source(mut self, source: impl Into<Source>) -> Self {
        self.0.source = Some(source.into());
        self
    }

    pub fn kind(&self) -> ErrorKind {
        self.0.kind
    }

    pub fn message(&self) -> &str {
        &self.0.message
    }

    pub fn status(&self) -> Option<u16> {
        self.0.status
    }

    pub fn body(&self) -> Option<&Value> {
        self.0.body.as_ref()
    }

    pub fn errors(&self) -> Option<&[Value]> {
        self.0.errors.as_deref()
    }

    /// Whether the same command may succeed later: rate limits, server errors, no response.
    pub fn is_retryable(&self) -> bool {
        match self.0.kind {
            ErrorKind::Network | ErrorKind::Timeout => true,
            ErrorKind::Api => matches!(self.0.status, Some(408 | 429 | 500..=599)),
            _ => false,
        }
    }

    pub fn exit_code(&self) -> u8 {
        match self.0.kind {
            ErrorKind::Usage => exit::USAGE,
            ErrorKind::Config => exit::CONFIG,
            ErrorKind::Api if matches!(self.0.status, Some(400..=499)) => exit::API_CLIENT,
            ErrorKind::Api => exit::API_SERVER,
            ErrorKind::Network | ErrorKind::Timeout => exit::NETWORK,
            ErrorKind::Decode | ErrorKind::Internal => exit::INTERNAL,
            ErrorKind::Output => exit::OUTPUT,
        }
    }

    /// Writing to a closed pipe (`acme things list | head`): the run stops quietly.
    pub fn is_broken_pipe(&self) -> bool {
        self.0
            .source
            .as_deref()
            .and_then(|source| source.downcast_ref::<io::Error>())
            .is_some_and(|error| error.kind() == io::ErrorKind::BrokenPipe)
    }

    /// `{"error": {"kind", "status", "message", "body", "request_id", "retryable",
    /// "retry_after", "errors"}}`, every key always present.
    pub fn to_json(&self) -> Value {
        json!({
            "error": {
                "kind": self.0.kind.as_str(),
                "status": self.0.status,
                "message": self.0.message,
                "body": self.0.body,
                "request_id": self.0.request_id,
                "retryable": self.is_retryable(),
                "retry_after": self.0.retry_after,
                "errors": self.0.errors,
            }
        })
    }

    /// The messages of the underlying errors, outermost first.
    pub fn causes(&self) -> Vec<String> {
        let mut causes = Vec::new();
        let mut source = std::error::Error::source(self);
        while let Some(error) = source {
            causes.push(error.to_string());
            source = error.source();
        }
        causes
    }

    /// Writes the error for a person (`human`) or as one line of JSON for a program, which
    /// `debug` gives `causes`.
    pub fn render(&self, w: &mut dyn io::Write, style: ErrorStyle) -> io::Result<()> {
        if !style.human {
            let mut json = self.to_json();
            if style.debug {
                json["error"]["causes"] = json!(self.causes());
            }
            return writeln!(w, "{json}");
        }
        let label = if style.color {
            "\x1b[1;31merror:\x1b[0m"
        } else {
            "error:"
        };
        writeln!(w, "{label} {}", self.0.message)?;
        if let Some(request_id) = &self.0.request_id {
            writeln!(w, "  request id: {request_id}")?;
        }
        if let Some(body) = self
            .0
            .body
            .as_ref()
            .filter(|body| style.debug || !is_message_only(body))
        {
            let pretty = serde_json::to_string_pretty(body).unwrap_or_default();
            for line in pretty.lines() {
                writeln!(w, "  {line}")?;
            }
        }
        if style.debug {
            for cause in self.causes() {
                writeln!(w, "  caused by: {cause}")?;
            }
        }
        Ok(())
    }
}

/// How [`CliError::render`] writes: for a person on a terminal, or as JSON.
#[derive(Clone, Copy, Debug, Default)]
pub struct ErrorStyle {
    pub human: bool,
    pub color: bool,
    pub debug: bool,
}

impl fmt::Display for CliError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0.message)
    }
}

impl std::error::Error for CliError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        self.0
            .source
            .as_deref()
            .map(|s| s as &(dyn std::error::Error + 'static))
    }
}

impl From<io::Error> for CliError {
    fn from(error: io::Error) -> Self {
        Self::internal(format!("I/O error: {error}")).with_source(error)
    }
}

impl From<serde_json::Error> for CliError {
    fn from(error: serde_json::Error) -> Self {
        Self::internal(format!("JSON error: {error}")).with_source(error)
    }
}

const MESSAGE_KEYS: [&str; 4] = ["message", "error", "detail", "title"];

/// The human message of an error body: `message`, `error`, `error.message`, `detail` or `title`.
fn body_message(body: &Value) -> Option<String> {
    match body {
        Value::String(text) if !text.trim().is_empty() => Some(text.trim().to_owned()),
        Value::Object(map) => MESSAGE_KEYS.iter().find_map(|key| match map.get(*key)? {
            Value::String(text) => Some(text.clone()),
            nested @ Value::Object(_) => body_message(nested),
            _ => None,
        }),
        _ => None,
    }
}

fn is_message_only(body: &Value) -> bool {
    match body {
        Value::String(_) => true,
        Value::Object(map) => {
            map.len() == 1
                && MESSAGE_KEYS
                    .iter()
                    .any(|key| map.get(*key).is_some_and(Value::is_string))
        }
        _ => false,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn rendered(error: &CliError, style: ErrorStyle) -> String {
        let mut out = Vec::new();
        error.render(&mut out, style).unwrap();
        String::from_utf8(out).unwrap()
    }

    #[test]
    fn exit_codes_follow_the_kind_and_status() {
        assert_eq!(CliError::usage("x").exit_code(), exit::USAGE);
        assert_eq!(CliError::config("x").exit_code(), exit::CONFIG);
        assert_eq!(CliError::api(404, b"").exit_code(), exit::API_CLIENT);
        assert_eq!(CliError::api(429, b"").exit_code(), exit::API_CLIENT);
        assert_eq!(CliError::api(503, b"").exit_code(), exit::API_SERVER);
        assert_eq!(CliError::api(302, b"").exit_code(), exit::API_SERVER);
        assert_eq!(CliError::timeout().exit_code(), exit::NETWORK);
        assert_eq!(CliError::network("refused").exit_code(), exit::NETWORK);
        assert_eq!(CliError::decode("bad").exit_code(), exit::INTERNAL);
        assert_eq!(CliError::internal("bug").exit_code(), exit::INTERNAL);
    }

    #[test]
    fn api_errors_take_their_message_from_the_body() {
        let error = CliError::api(404, br#"{"message": "No such thing: th_9"}"#);
        assert_eq!(error.message(), "API error 404: No such thing: th_9");
        let nested = CliError::api(
            400,
            br#"{"error": {"message": "bad currency", "param": "currency"}}"#,
        );
        assert_eq!(nested.message(), "API error 400: bad currency");
        let text = CliError::api(502, b"Bad Gateway\n");
        assert_eq!(text.message(), "API error 502: Bad Gateway");
        assert_eq!(text.body(), Some(&json!("Bad Gateway\n")));
        assert_eq!(CliError::api(500, b"").message(), "API error 500");
    }

    #[test]
    fn json_rendering_has_a_fixed_shape() {
        let error = CliError::api(422, br#"{"message": "name is required", "field": "name"}"#)
            .with_request_id(Some("req_1"));
        assert_eq!(
            rendered(&error, ErrorStyle::default()),
            concat!(
                r#"{"error":{"kind":"api","status":422,"message":"API error 422: name is required","#,
                r#""body":{"message":"name is required","field":"name"},"request_id":"req_1","#,
                r#""retryable":false,"retry_after":null,"errors":null}}"#,
                "\n"
            )
        );
        assert_eq!(
            rendered(&CliError::timeout(), ErrorStyle::default()),
            concat!(
                r#"{"error":{"kind":"timeout","status":null,"message":"request timed out","body":null,"#,
                r#""request_id":null,"retryable":true,"retry_after":null,"errors":null}}"#,
                "\n"
            )
        );
    }

    #[test]
    fn retryable_errors_say_so_with_their_delay() {
        let limited = CliError::api(429, b"").with_retry_after(Some(30));
        assert!(limited.is_retryable());
        assert_eq!(limited.to_json()["error"]["retry_after"], json!(30));
        assert!(CliError::api(503, b"").is_retryable());
        assert!(CliError::network("refused").is_retryable());
        assert!(!CliError::api(404, b"").is_retryable());
        assert!(!CliError::usage("x").is_retryable());
    }

    #[test]
    fn input_errors_are_listed_and_joined() {
        let error = CliError::invalid_input(
            "body",
            vec![
                json!({"path": "address.zip", "flag": "--address", "message": "unknown field"}),
                json!({"path": "name", "flag": null, "message": "required"}),
            ],
        );
        assert_eq!(
            error.message(),
            "invalid body: address.zip (--address): unknown field; name: required"
        );
        assert_eq!(error.exit_code(), exit::USAGE);
        assert_eq!(error.to_json()["error"]["errors"][1]["path"], json!("name"));
    }

    #[test]
    fn messages_are_not_prefixed_twice() {
        let error = CliError::api(400, br#"{"message": "API error: bad"}"#);
        assert_eq!(error.message(), "API error: bad");
        assert_eq!(CliError::output("x").exit_code(), exit::OUTPUT);
    }

    #[test]
    fn human_rendering_shows_the_body_unless_it_only_repeats_the_message() {
        let style = ErrorStyle {
            human: true,
            ..ErrorStyle::default()
        };
        let plain = CliError::api(404, br#"{"message": "not found"}"#);
        assert_eq!(rendered(&plain, style), "error: API error 404: not found\n");
        let detailed = CliError::api(422, br#"{"message": "invalid", "field": "name"}"#)
            .with_request_id(Some("req_2"));
        assert_eq!(
            rendered(&detailed, style),
            "error: API error 422: invalid\n  request id: req_2\n  {\n    \"message\": \"invalid\",\n    \"field\": \"name\"\n  }\n"
        );
        let colored = ErrorStyle {
            color: true,
            ..style
        };
        assert!(rendered(&CliError::usage("bad flag"), colored)
            .starts_with("\x1b[1;31merror:\x1b[0m bad flag"));
    }

    #[test]
    fn debug_rendering_prints_the_cause_chain() {
        let io = io::Error::new(io::ErrorKind::ConnectionRefused, "refused");
        let error = CliError::network("refused").with_source(io);
        let style = ErrorStyle {
            human: true,
            debug: true,
            ..ErrorStyle::default()
        };
        assert_eq!(
            rendered(&error, style),
            "error: connection error: refused\n  caused by: refused\n"
        );
        let json: Value = serde_json::from_str(&rendered(
            &error,
            ErrorStyle {
                human: false,
                ..style
            },
        ))
        .unwrap();
        assert_eq!(json["error"]["causes"], json!(["refused"]));
    }

    #[test]
    fn broken_pipes_are_recognized() {
        let error: CliError = io::Error::from(io::ErrorKind::BrokenPipe).into();
        assert!(error.is_broken_pipe());
        assert!(!CliError::internal("x").is_broken_pipe());
    }
}
